! The mpi_f08 wrappers, MPI_ and PMPI_ alike, over a second set of interfaces
! to the same C entry points. See dev/mpiapi.jl; do not edit.

module mpif_f08_raw
  use mpif_constants
  use mpif_f08_types, only: MPI_Status
  implicit none
  public
  save

  interface

     subroutine MPI_File_read( &
       fh, &
       buf, &
       count, &
       datatype, &
       status, &
       ierror &
     )
       use mpif_constants
       import :: MPI_Status
       implicit none
       integer :: fh
       !dir$ ignore_tkr(trk) buf
       !gcc$ attributes no_arg_check :: buf
       integer :: buf(*)
       integer :: count
       integer :: datatype
       type(MPI_Status) :: status
       integer :: ierror
     end subroutine MPI_File_read

