  subroutine MPI_Abi_get_fortran_booleans( &
    logical_size, &
    logical_true, &
    logical_false, &
    is_set, &
    ierror &
  )
    use mpif_f08_constants
    use mpif_f08_types
    implicit none
    integer, intent(in) :: logical_size
    logical, intent(out) :: logical_true
    logical, intent(out) :: logical_false
    logical, intent(out) :: is_set
    integer, intent(out), optional :: ierror
    integer :: tmp_ierror
    call MPIF_Abi_get_fortran_booleans( &
      logical_size, &
      logical_true, &
      logical_false, &
      is_set, &
      tmp_ierror &
    )
    if (present(ierror)) ierror = tmp_ierror
  end subroutine MPI_Abi_get_fortran_booleans

  subroutine PMPI_Abi_get_fortran_booleans( &
    logical_size, &
    logical_true, &
    logical_false, &
    is_set, &
    ierror &
  )
    use mpif_f08_constants
    use mpif_f08_types
    implicit none
    integer, intent(in) :: logical_size
    logical, intent(out) :: logical_true
    logical, intent(out) :: logical_false
    logical, intent(out) :: is_set
    integer, intent(out), optional :: ierror
    integer :: tmp_ierror
    call PMPIF_Abi_get_fortran_booleans( &
      logical_size, &
      logical_true, &
      logical_false, &
      is_set, &
      tmp_ierror &
    )
    if (present(ierror)) ierror = tmp_ierror
  end subroutine PMPI_Abi_get_fortran_booleans

  subroutine MPI_Abi_get_fortran_info( &
    info, &
    ierror &
  )
    use mpif_f08_constants
    use mpif_f08_types
    implicit none
    type(MPI_Info), intent(out) :: info
    integer, intent(out), optional :: ierror
    integer :: tmp_ierror
    call MPIF_Abi_get_fortran_info( &
